  GVTypes[15]=strdup("short");
  GVNames[16]=strdup("maliciousCANMessagesTime");
  GVTypes[16]=strdup("short");
  GVNames[17]=strdup("maliciousV2XMessagesCost");
  GVTypes[17]=strdup("short");
  GVNames[18]=strdup("maliciousV2XMessagesTime");
  GVTypes[18]=strdup("short");
