  GVTypes[21]=strdup("short");
  GVNames[22]=strdup("v2XPacketCraftingSkillThreshold");
  GVTypes[22]=strdup("short");

  // create the arrays to store the values of each gv
  CANExtractionCostValues = new short[NumExps];
  CANExtractionSkillThresholdValues = new short[NumExps];
  CANExtractionTimeValues = new short[NumExps];
  CANSpoofingSkillThresholdValues = new short[NumExps];
  OEMSpoofingSkillThresholdValues = new short[NumExps];
  chipFlashingSkillLevelValues = new short[NumExps];
  chipFlashingSkillThresholdValues = new short[NumExps];
  dataExtractionSkillLevelValues = new short[NumExps];
  hasCarModelKnowledgeValues = new bool[NumExps];
  hasMessageFormatKnowledgeValues = new bool[NumExps];
  hasProximityAccessValues = new bool[NumExps];
  hasRemoteNetworkAccessValues = new bool[NumExps];
  hasV2XProtocolKnowledgeValues = new bool[NumExps];
  injectionSkillLevelValues = new short[NumExps];
  injectionSkillThresholdValues = new short[NumExps];
  maliciousCANMessagesCostValues = new short[NumExps];
  maliciousCANMessagesTimeValues = new short[NumExps];
  maliciousV2XMessagesCostValues = new short[NumExps];
